package com.company.platform.inventory.infrastructure;
import com.company.platform.inventory.domain.Warehouse;import java.sql.Timestamp;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class JdbcWarehouseStore{private final JdbcTemplate jdbc;public JdbcWarehouseStore(JdbcTemplate j){jdbc=j;}public Warehouse save(Warehouse w){jdbc.update("INSERT INTO warehouses(id,tenant_id,code,name,active,created_at) VALUES(?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=?,active=?",w.id(),w.tenantId(),w.code(),w.name(),w.active(),Timestamp.from(w.createdAt()),w.name(),w.active());return w;}public Optional<Warehouse> find(UUID t,UUID id){return jdbc.query("SELECT * FROM warehouses WHERE tenant_id=? AND id=?",(r,n)->new Warehouse((UUID)r.getObject("id"),(UUID)r.getObject("tenant_id"),r.getString("code"),r.getString("name"),r.getBoolean("active"),r.getTimestamp("created_at").toInstant()),t,id).stream().findFirst();}public List<Warehouse> findAll(UUID t){return jdbc.query("SELECT * FROM warehouses WHERE tenant_id=? ORDER BY name",(r,n)->new Warehouse((UUID)r.getObject("id"),(UUID)r.getObject("tenant_id"),r.getString("code"),r.getString("name"),r.getBoolean("active"),r.getTimestamp("created_at").toInstant()),t);}}
